#!/bin/bash
# channel=kalmannet-daily-perbasin sequence=91 purpose=A40-refresh-admit-single-submit
set -euo pipefail
set -C
umask 077
/data1/home/sunyiq/miniconda3/envs/nh_final/bin/python -I -B - <<'A40_COMBINED_SUBMISSION'
import base64
from hashlib import sha256
import importlib.util
from pathlib import Path
import stat
import time

ROOT = Path('/data1/home/sunyiq/kalmannet_daily_camels_per_basin_21_development_20260908')
REQUEST = ROOT / 'runtime/train_08190500_A40_entryrepair_seq91'
DEPLOYMENT = ROOT / 'deployment_A40_entry_repair_20260910_SEQ90'
EVIDENCE = ROOT / 'runtime/refresh_A40_SEQ91_proof_20260910'
INDEX_SHA = '65273833c2a31c088dd1a2577105c42cb93e5562e602f072dc4f33dd3b3b3d2d'
ADMISSION_SHA = 'b5bec9163aea0a1f4fc12e87a9dff719dda18d220679d0e8fbd0c7bb361abfd0'
IDENTITY_SHA = 'e8021a47267146c4c610817f41f0802435cb085ee48d8547c02c5f8e5d6ad173'


def proof(admission, spec, paths, live, raw):
    return {'phase': 'deployment', 'candidate_index_sha256': INDEX_SHA,
            'request_sha256': sha256(admission.encode(spec)).hexdigest(),
            'live': live, 'paths': paths, 'raw_evidence_sha256': sha256(raw).hexdigest()}


TEMPLATE_BASE64 = ''
TEMPLATE_SHA = '5afd977f9f0f388ee075df4d6c0d5047014b11e3c268acf3cadeb34b77be4740'


def bind_fresh(admission, template, result, raw, reserved_at):
    envelope = admission.strict(template)
    evidence = dict(envelope['evidence_base64'])
    for key in ('deployment_proof_sha256', 'deployment_raw_evidence_sha256'):
        evidence.pop(envelope[key])
    for key, value in (('deployment_proof_sha256', result), ('deployment_raw_evidence_sha256', raw)):
        digest = sha256(value).hexdigest()
        envelope[key] = digest
        evidence[digest] = base64.b64encode(value).decode()
    envelope['evidence_base64'] = evidence
    envelope['reserved_at_seconds'] = reserved_at
    return envelope


def main():
    source = REQUEST / 'successor_admission.py'
    for path in (source, *source.parents):
        info = path.lstat()
        if stat.S_ISLNK(info.st_mode) or getattr(info, 'st_file_attributes', 0) & stat.FILE_ATTRIBUTE_REPARSE_POINT:
            raise ValueError('bootstrap link/reparse forbidden')
    if source.resolve(strict=True) != source or sha256(source.read_bytes()).hexdigest() != ADMISSION_SHA:
        raise ValueError('accepted admission bootstrap differs')
    module_spec = importlib.util.spec_from_file_location('refresh_accepted_admission', source)
    admission = importlib.util.module_from_spec(module_spec)
    module_spec.loader.exec_module(admission)
    spec = admission.staged(REQUEST, INDEX_SHA)
    admission.require(spec['sequence'] == 91 and spec['request_directory'] == str(REQUEST)
                      and spec['workspace'] == str(DEPLOYMENT / 'workspace'), 'fixed experiment request differs')
    parser = admission.load('refresh_metadata', REQUEST / 'precheck_live_submission_check.py', admission.PARSER_SHA)
    helper = admission.load('refresh_scheduler', REQUEST / 'first_training_admission_check.py', admission.HELPER_SHA)
    identity = admission.strict(admission.raw_file(REQUEST / 'a40-workspace-identity.json', IDENTITY_SHA))
    admission.require(identity['deployment_directory'] == str(DEPLOYMENT) and len(identity['files']) == 103,
                      'exact deployed scientific identity differs')

    def recheck():
        admission.require(admission.staged(REQUEST, INDEX_SHA) == spec, 'request changed during refresh')
        paths = admission.targets(spec, parser)
        for path in (REQUEST / 'admission.json', REQUEST / 'submission_livecheck_seq91'):
            admission.canonical(path, absent=True)
        parser.real_directory(DEPLOYMENT)
        members = set()
        for path in DEPLOYMENT.rglob('*'):
            admission.canonical(path)
            if path.is_dir():
                continue
            name = path.relative_to(DEPLOYMENT).as_posix()
            admission.require(name in identity['files'], 'unexpected deployed member')
            item = identity['files'][name]
            admission.require(len(admission.raw_file(path, item['sha256'])) == item['bytes'], 'deployed member size differs')
            members.add(name)
        admission.require(members == set(identity['files']), 'missing deployed member')
        parser.current_authority({'valid_from_seconds': 1788878005, 'valid_until_seconds': admission.EXPIRY}, int(time.time()))
        return paths

    recheck()
    # All writes are exclusive and confined to this new, isolated evidence root.
    admission.canonical(EVIDENCE, absent=True).mkdir()
    recorder = parser.QueryRecorder(EVIDENCE)
    live = helper.run_scheduler_checks(recorder, parser)
    parser.freshness(recorder.observed, int(time.time()))
    helper.bundle_raw_evidence(EVIDENCE)
    raw = admission.raw_file(EVIDENCE / 'raw-evidence.json')
    admission.require(len(raw) <= 300000, 'raw evidence transport bound exceeded')
    admission.verify_raw_bundle(admission.strict(raw), parser, live, helper)
    paths = recheck()
    parser.freshness(recorder.observed, int(time.time()))
    result = admission.encode(proof(admission, spec, paths, live, raw))
    admission.require(len(result) <= 32000, 'deployment proof transport bound exceeded')
    admission.save(EVIDENCE / 'success.json', result)
    print('DEPLOYMENT_PROOF_BASE64=' + base64.b64encode(result).decode(), flush=True)
    print('DEPLOYMENT_RAW_EVIDENCE_BASE64=' + base64.b64encode(raw).decode(), flush=True)
    template = base64.b64decode(TEMPLATE_BASE64, validate=True)
    admission.require(sha256(template).hexdigest() == TEMPLATE_SHA, 'static admission template differs')
    envelope = bind_fresh(admission, template, result, raw, recorder.observed)
    guard = admission.load('refresh_guard', DEPLOYMENT / 'workspace/scripts/daily_camels_development_guard.py', admission.GUARD_SHA)
    admission.validate(envelope, spec, INDEX_SHA, guard, parser, int(time.time()), helper)
    recheck()
    admission_raw = admission.encode(envelope)
    admission.save(REQUEST / 'admission.json', admission_raw)
    print('ADMISSION_SHA256=' + sha256(admission_raw).hexdigest(), flush=True)
    # The unchanged phase repeats fresh scheduler checks and owns the sole sbatch call.
    admission.phase('submission', INDEX_SHA, sha256(admission_raw).hexdigest())


if __name__ == '__main__':
    main()

A40_COMBINED_SUBMISSION
